import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createResponsiveResolver } from "./theme-core/responsive-layouts.mjs";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(projectRoot, "studio", "responsive-resolver.js");
const output = [
  "// Generated by scripts/build-responsive-resolver.mjs. Do not edit by hand.",
  `window.CLAUDE_AURA_RESPONSIVE_RESOLVER_FACTORY = ${createResponsiveResolver.toString()};`,
  "",
].join("\n");

await fs.writeFile(outputPath, output, "utf8");
